//! Example Rust extension, built as a `cdylib` and loaded by the running
//! application (`blablablars run --rust-plugin <path-to-this-.so>`).
//!
//! ```sh
//! cargo build --manifest-path examples/rust-plugin/Cargo.toml
//! ```
//!
//! The `#[no_mangle]` entry point and the whole vtable are generated by
//! `export_plugin!`; a plugin author only writes the `Extension` impl.
#![allow(unsafe_code)]

use blablablars_core::{export_plugin, Extension, ExtensionError, HOOKS, HOOK_INPUT, HOOK_OUTPUT};
use serde_json::{json, Value};

/// Uppercases incoming text and tags the analysis on the way out.
struct Shout {
    hooks: Vec<String>,
}

impl Shout {
    fn new() -> Self {
        Self {
            hooks: vec![HOOK_INPUT.to_string(), HOOK_OUTPUT.to_string()],
        }
    }
}

impl Extension for Shout {
    fn name(&self) -> &str {
        "shout"
    }

    fn hooks(&self) -> &[String] {
        &self.hooks
    }

    fn call(&self, hook: &str, payload: &Value) -> Result<Value, ExtensionError> {
        match hook {
            HOOK_INPUT => {
                let text = payload
                    .get("text")
                    .and_then(Value::as_str)
                    .ok_or_else(|| ExtensionError::InvalidPayload {
                        hook: hook.to_string(),
                        message: "expected a string `text`".into(),
                    })?;
                Ok(json!({ "text": format!("[shouted] {}", text.to_uppercase()) }))
            }
            HOOK_OUTPUT => {
                let mut output = payload.clone();
                if let Some(analysis) = output.get_mut("analysis").and_then(Value::as_object_mut) {
                    analysis.insert("extension".into(), json!("shout"));
                }
                Ok(output)
            }
            other => Err(ExtensionError::failed(
                self.name(),
                other,
                format!("`shout` only understands {HOOKS:?}"),
            )),
        }
    }
}

export_plugin!(::std::sync::Arc::new(Shout::new()));
